"""Qualitative review generated by the finalized classifier's evaluate()."""

from __future__ import annotations

import csv
import hashlib
import html
from pathlib import Path

import numpy as np
from PIL import Image, ImageDraw, ImageFont

from data import TMCADSource, save_json
from step_render import render_step


OUTCOMES = ("corrected", "worsened", "still_wrong", "still_correct")
COLORS = {
    "corrected": "#157347", "worsened": "#b42318",
    "still_wrong": "#a15c00", "still_correct": "#315477",
}


def _font(size: int, bold: bool = False):
    path = Path("C:/Windows/Fonts") / ("arialbd.ttf" if bold else "arial.ttf")
    return (ImageFont.truetype(str(path), size) if path.is_file()
            else ImageFont.load_default())


def _chart(classes: list[str], baseline: dict, final: dict,
           selected: str, final_name: str, path: Path) -> None:
    import matplotlib
    matplotlib.use("Agg")
    from matplotlib import pyplot as plt

    position = np.arange(len(classes))
    figure, (overview, recalls) = plt.subplots(
        2, 1, figsize=(13, 9), gridspec_kw={"height_ratios": [1, 2]},
    )
    try:
        for score, offset, color, name in (
            (baseline, -0.18, "#3565a2", "Fresh 512-D base"),
            (final, 0.18, "#dd8124", final_name),
        ):
            overview.bar(np.arange(3) + offset,
                         [score[key] for key in
                          ("accuracy", "balanced_accuracy", "macro_f1")],
                         width=0.36, color=color, label=name)
            recalls.bar(position + offset,
                        [score["per_class"][part]["recall"] for part in classes],
                        width=0.36, color=color)
        overview.set_xticks(np.arange(3),
                            ["Accuracy", "Balanced accuracy", "Macro-F1"])
        recalls.set_xticks(position, classes, rotation=35, ha="right")
        for axis in (overview, recalls):
            axis.set_ylim(0, 1.04)
            axis.grid(axis="y", alpha=0.2)
        overview.set_ylabel("Held-out test score")
        recalls.set_ylabel("Held-out test recall")
        overview.legend(loc="lower right")
        figure.suptitle(f"TMCAD frozen JEPA classifier | validation selected {selected}",
                        fontsize=15)
        figure.text(0.5, 0.01,
                    "Test examples illustrate predictions; they were not used for model selection.",
                    ha="center", fontsize=10)
        figure.tight_layout(rect=(0, 0.035, 1, 0.95))
        path.parent.mkdir(parents=True, exist_ok=True)
        figure.savefig(path, dpi=160, facecolor="white")
    finally:
        plt.close(figure)


def _card(row: dict, views: list[str], final_name: str,
          destination: Path) -> None:
    size = 300
    card = Image.new("RGB", (930, 372), "white")
    draw = ImageDraw.Draw(card)
    color = COLORS[row["outcome"]]
    draw.rectangle((0, 0, 929, 371), outline=color, width=3)
    draw.rectangle((0, 0, 930, 38), fill=color)
    draw.text((12, 9), f"{row['true_class']} | {row['outcome']}",
              fill="white", font=_font(17, True))
    for index, path in enumerate(views):
        with Image.open(path) as source:
            picture = source.convert("RGB")
            picture.thumbnail((288, 288), Image.Resampling.LANCZOS)
            x = index * size + (size - picture.width) // 2
            y = 42 + (size - picture.height) // 2
            card.paste(picture, (x, y))
    x = 612
    draw.text((x, 53), f"Ground truth: {row['true_class']}",
              fill="#172b4d", font=_font(17, True))
    for label, key, confidence_key, top in (
        ("512-D base", "baseline_prediction", "baseline_confidence", 104),
        (final_name, "final_prediction", "final_confidence", 164),
    ):
        prediction = row[key]
        correct = prediction == row["true_class"]
        draw.text((x, top), f"{label}: {prediction}",
                  fill="#157347" if correct else "#b42318",
                  font=_font(17, True))
        draw.text((x, top + 24),
                  f"confidence: {float(row[confidence_key]):.3f}",
                  fill="#526176", font=_font(14))
    uid = row["uid"]
    if len(uid) > 38:
        uid = uid[:35] + "..."
    draw.text((x, 250), f"ID: {uid}", fill="#526176", font=_font(13))
    draw.text((x, 278), "Actual STEP, opposite views",
              fill="#526176", font=_font(13))
    destination.parent.mkdir(parents=True, exist_ok=True)
    card.save(destination)


def _sheet(class_name: str, cases: list[dict], final_name: str,
           destination: Path) -> None:
    if not cases:
        return
    title_height, gap, card_height = 55, 10, 372
    sheet = Image.new("RGB", (930, title_height + len(cases) * (card_height + gap)),
                      "#edf2f6")
    draw = ImageDraw.Draw(sheet)
    draw.text((14, 15), f"{class_name}: 512-D base versus {final_name}",
              fill="#172b4d", font=_font(22, True))
    for index, case in enumerate(cases):
        with Image.open(case["card_path"]) as card:
            sheet.paste(card.convert("RGB"),
                        (0, title_height + index * (card_height + gap)))
    destination.parent.mkdir(parents=True, exist_ok=True)
    sheet.save(destination)


def render_final_results(source: TMCADSource, output: Path,
                         baseline: dict, final: dict, selected: str,
                         predictions: list[dict], settings: dict) -> dict:
    """Render deterministic, class/outcome-stratified held-out STEP cases.

    Only display tessellation is capped. The trained inputs and predictions
    are not changed. Every failed STEP import is retained in the audit.
    """
    target = output / "visualization"
    target.mkdir(parents=True, exist_ok=True)
    # Always display the actual residual arm; test visualization never changes
    # the validation-only choice of which classifier to deploy.
    final_name = "Physical residual (196-D)"
    indices = source.indices["test"]
    if len(predictions) != len(indices):
        raise ValueError("Qualitative predictions differ from test split length")
    for row, index in zip(predictions, indices, strict=True):
        if (row["uid"] != source.metadata["uids"][int(index)]
                or Path(row["step_path"]).resolve() != source.sample_path(int(index))
                or row["true_class"] != source.classes[int(source.labels[index])]
                or row["outcome"] not in OUTCOMES):
            raise ValueError(f"Qualitative row mismatches TMCAD sample {row['uid']}")
    _chart(source.classes, baseline, final, selected, final_name,
           target / "metric_comparison.png")
    summary = []
    for class_name in source.classes:
        own = [row for row in predictions if row["true_class"] == class_name]
        first = baseline["per_class"][class_name]
        second = final["per_class"][class_name]
        summary.append({
            "class": class_name, "test_n": len(own),
            "baseline_recall": first["recall"],
            "final_recall": second["recall"],
            "recall_change_pp": 100 * (second["recall"] - first["recall"]),
            **{name: sum(row["outcome"] == name for row in own)
               for name in OUTCOMES},
        })
    with (target / "class_change_summary.csv").open(
            "w", encoding="utf-8", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=list(summary[0]))
        writer.writeheader()
        writer.writerows(summary)
    per_group = int(settings["cases_per_class_outcome"])
    image_size = int(settings["image_size"])
    triangle_limit = int(settings["max_render_triangles"])
    edge_limit = int(settings["max_render_edges"])
    if (not 1 <= per_group <= 5 or not 200 <= image_size <= 700
            or not 1000 <= triangle_limit <= 100000
            or not 0 <= edge_limit <= 2000):
        raise ValueError("Invalid qualitative rendering settings")
    selected_cases = []
    for class_name in source.classes:
        for outcome in OUTCOMES:
            group = [row for row in predictions if row["true_class"] == class_name
                     and row["outcome"] == outcome]
            group.sort(key=lambda row: (-max(float(row["baseline_confidence"]),
                                                 float(row["final_confidence"])),
                                        row["uid"]))
            selected_cases.extend(group[:per_group])
    if not selected_cases:
        raise ValueError("No held-out qualitative cases could be selected")
    try:
        import OCP  # noqa: F401
    except ImportError as error:
        raise ImportError(
            "Quantitative evaluation was saved, but rendering actual STEP solids "
            "requires cadquery-ocp (OCP). Install it and rerun --stage evaluate."
        ) from error
    cases = []
    for position, row in enumerate(selected_cases, 1):
        stem = hashlib.sha256(row["uid"].encode("utf-8")).hexdigest()[:16]
        try:
            details = render_step(Path(row["step_path"]), target / "parts" / stem,
                                  image_size, triangle_limit, edge_limit)
            card_path = target / "cards" / f"{stem}.png"
            _card(row, details["views"], final_name, card_path)
            details["card_path"] = str(card_path)
        except Exception as error:
            details = {"status": "invalid", "step_path": row["step_path"],
                       "error": f"{type(error).__name__}: {error}"}
        cases.append({**row, **details})
        print(f"Qualitative STEP render {position}/{len(selected_cases)} "
              f"{row['true_class']} {row['outcome']} {details['status']}", flush=True)
    valid = [case for case in cases if case["status"] == "valid"]
    sheets = []
    for class_name in source.classes:
        own = [case for case in valid if case["true_class"] == class_name]
        if own:
            path = target / f"class_{class_name}.png"
            _sheet(class_name, own, final_name, path)
            sheets.append(path)
    fieldnames = list(selected_cases[0]) + [
        "status", "card_path", "views", "triangles_in_step_tessellation",
        "triangles_rendered", "topological_edges", "edges_rendered", "error",
    ]
    with (target / "rendered_cases.csv").open(
            "w", encoding="utf-8", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=fieldnames,
                                extrasaction="ignore")
        writer.writeheader()
        writer.writerows(cases)
    audit = {
        "source": "Held-out TMCAD test; actual imported STEP solids",
        "requested": len(selected_cases), "valid": len(valid),
        "invalid": len(cases) - len(valid), "cases": cases,
        "metric_chart": str(target / "metric_comparison.png"),
        "class_sheets": [str(path) for path in sheets],
    }
    save_json(target / "render_audit.json", audit)
    table = "\n".join(
        "<tr>"
        f"<td>{html.escape(item['class'])}</td>"
        f"<td>{item['test_n']}</td>"
        f"<td>{item['baseline_recall']:.3f}</td>"
        f"<td>{item['final_recall']:.3f}</td>"
        f"<td>{item['recall_change_pp']:+.1f}</td>"
        f"<td>{item['corrected']}</td>"
        f"<td>{item['worsened']}</td>"
        "</tr>" for item in summary
    )
    links = "\n".join(
        f'<li><a href="{html.escape(path.name)}">'
        f'{html.escape(path.stem.removeprefix("class_"))}</a></li>'
        for path in sheets
    )
    (target / "index.html").write_text(
        "<!doctype html><html lang=\"en\"><meta charset=\"utf-8\">"
        "<title>TMCAD final classifier qualitative review</title>"
        "<style>body{font:16px system-ui;max-width:1050px;margin:32px auto;"
        "color:#172b4d}img{max-width:100%}li{margin:6px 0}"
        "table{border-collapse:collapse}th,td{padding:7px 10px;"
        "border-bottom:1px solid #d4dce5;text-align:right}"
        "td:first-child,th:first-child{text-align:left}</style>"
        f"<h1>Fresh 512-D classifier and {html.escape(final_name)}</h1>"
        f"<p>Validation-selected model: {html.escape(selected)}. "
        "The held-out test cases below explain changes but were not used "
        "to choose the model.</p>"
        '<img src="metric_comparison.png" alt="Class-wise baseline versus final metrics">'
        "<h2>Where did predictions improve or worsen?</h2>"
        "<p>Recall change is in percentage points. Corrected means the 512-D "
        "base was wrong and the residual was right; worsened is the reverse.</p>"
        "<table><tr><th>Class</th><th>Test parts</th><th>Base recall</th>"
        "<th>Final recall</th><th>Change (pp)</th><th>Corrected</th>"
        f"<th>Worsened</th></tr>{table}</table>"
        "<h2>Actual STEP parts, shown from two sides</h2>"
        f"<p>Valid renders: {len(valid)}/{len(selected_cases)}. "
        "See render_audit.json for any render failures.</p>"
        f"<ul>{links}</ul></html>", encoding="utf-8",
    )
    print(f"Final qualitative review: {target / 'index.html'} "
          f"({len(valid)}/{len(selected_cases)} valid STEP renders)", flush=True)
    if not valid:
        raise RuntimeError(f"No STEP cases rendered; inspect {target / 'render_audit.json'}")
    return audit
